head.script:
scwin.getCurrentData = function(split) {
    var mm = WebSquare.wUnit.getObjById("Calendar1_calendar_selectbox_month_label").innerText.split("월")[0];
    var yyyy = WebSquare.wUnit.getObjById("Calendar1_calendar_selectbox_year_label").innerText.split("년")[0];
    if (mm < 10) {
        mm = '0' + mm
    }
    today = yyyy + split + mm;
    return today;
}
scwin.checkVal1 = function() {
    return scwin.getCurrentData('-') == WebSquare.wUnit.getDomById('Calendar1_input').value;
}
scwin.checkVal2 = function() {
    return scwin.getCurrentData('') == WebSquare.wUnit.getDomById('Calendar11_input').value;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Calendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Calendar1_calendar_selectbox_month_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Calendar1_calendar_selectbox_month_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_header_btn_ok')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");

    //skipConfirm 적용 후
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Calendar11_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Calendar11_calendar_selectbox_month_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('Calendar11_calendar_selectbox_month_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    //Verify 2. 기존버전과 다르게 확인버튼이 숨김처리되어 있으며, 마지막 데이터 (월) 을 선택하면 자동으로 확인처리되어서 선택된 데이터가 입력된다.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2calendar_header_btn_ok').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
}
